"OLAYLAR_GEZGINLER:1770-01-10:0":{"b": ["Nyanda za juu za Uhabeshi (Aksum – Gondar)", "bb63d3ed"], "d": ["Njia: Aksum → Gondar. Safari nzima inaonyeshwa kwenye ramani kama mstari wa safari.", "9eabec22"]},
