"OLAYLAR_GEZGINLER:1770-06-11:0":{"b": ["Endeavour yakwama kwenye miamba", "02352e33"], "d": ["Katika Great Barrier Reef tarehe 11 Juni 1770 meli iligonga miamba na kukwama; mizigo ilitupwa na meli ikavutwa hadi Mto Endeavour kwa ukarabati.", "8634f9c6"]},
